import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { switchStyles } from './switch.styles.js';

export type SwitchSize = 'sm' | 'md';

/**
 * An on/off toggle switch with `role="switch"` and `aria-checked`.
 *
 * @element bl-switch
 * @slot - Label text for the switch.
 * @csspart track - The switch track.
 * @csspart thumb - The switch thumb.
 * @fires bl-change - Emitted when the checked state changes.
 */
@customElement('bl-switch')
export class BlSwitch extends LitElement {
  static override styles = [tokens, switchStyles];

  /** Whether the switch is on. */
  @property({ type: Boolean, reflect: true })
  checked = false;

  /** Whether the switch is disabled. */
  @property({ type: Boolean })
  disabled = false;

  /** Size of the switch. */
  @property({ reflect: true })
  size: SwitchSize = 'md';

  /** Form name. */
  @property()
  name = '';

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'switch');
    if (!this.hasAttribute('tabindex')) {
      this.setAttribute('tabindex', '0');
    }
    this.addEventListener('click', this._handleClick);
    this.addEventListener('keydown', this._handleKeyDown);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('click', this._handleClick);
    this.removeEventListener('keydown', this._handleKeyDown);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('checked')) {
      this.setAttribute('aria-checked', String(this.checked));
      if (this.checked) {
        this.setAttribute('data-checked', '');
      } else {
        this.removeAttribute('data-checked');
      }
    }
    if (changed.has('disabled')) {
      this.setAttribute('aria-disabled', String(this.disabled));
    }
  }

  private _handleClick = (): void => {
    if (this.disabled) return;
    this.checked = !this.checked;
    this._fireChange();
  };

  private _handleKeyDown = (e: KeyboardEvent): void => {
    if (this.disabled) return;
    if (e.key === ' ' || e.key === 'Enter') {
      e.preventDefault();
      this.checked = !this.checked;
      this._fireChange();
    }
  };

  private _fireChange(): void {
    this.dispatchEvent(
      new CustomEvent('bl-change', {
        detail: { checked: this.checked },
        composed: true,
        bubbles: true,
      }),
    );
  }

  protected override render() {
    return html`
      <span part="track" class="track">
        <span part="thumb" class="thumb"></span>
      </span>
      <span class="label"><slot></slot></span>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-switch': BlSwitch;
  }
}

import { css } from 'lit';

export const switchStyles = css`
  :host {
    display: inline-flex;
    align-items: center;
    gap: var(--bl-spacing-sm);
    cursor: pointer;
    user-select: none;
    font-family: var(--bl-font-family-base);
  }

  :host([aria-disabled='true']) {
    opacity: 0.5;
    cursor: not-allowed;
    pointer-events: none;
  }

  .track {
    position: relative;
    flex-shrink: 0;
    border-radius: var(--bl-radius-full);
    background-color: var(--bl-color-neutral-300);
    transition: background-color var(--bl-transition-fast);
  }

  :host([size='sm']) .track {
    width: 2rem;
    height: 1.125rem;
  }

  :host([size='md']) .track {
    width: 2.75rem;
    height: 1.5rem;
  }

  :host([size='sm']) {
    font-size: var(--bl-font-size-sm);
  }

  :host([size='md']) {
    font-size: var(--bl-font-size-md);
  }

  .thumb {
    position: absolute;
    top: 2px;
    left: 2px;
    border-radius: var(--bl-radius-full);
    background-color: white;
    transition: transform var(--bl-transition-fast);
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
  }

  :host([size='sm']) .thumb {
    width: calc(1.125rem - 4px);
    height: calc(1.125rem - 4px);
  }

  :host([size='md']) .thumb {
    width: calc(1.5rem - 4px);
    height: calc(1.5rem - 4px);
  }

  /* Checked */
  :host([data-checked]) .track {
    background-color: var(--bl-color-primary-600);
  }

  :host([data-checked][size='sm']) .thumb {
    transform: translateX(calc(2rem - 1.125rem));
  }

  :host([data-checked][size='md']) .thumb {
    transform: translateX(calc(2.75rem - 1.5rem));
  }

  /* Focus */
  :host(:focus-visible) .track {
    outline: var(--bl-focus-ring);
    outline-offset: var(--bl-focus-ring-offset);
  }

  /* Hover */
  :host(:hover:not([aria-disabled='true'])) .track {
    background-color: var(--bl-color-neutral-400);
  }

  :host([data-checked]:hover:not([aria-disabled='true'])) .track {
    background-color: var(--bl-color-primary-700);
  }

  .label {
    color: var(--bl-color-neutral-700);
  }
`;
